#include <iostream>
#include <string>
#include <vector>

int main() {
    int n, k;
    std::cin >> n >> k;
    std::string s;
    std::cin >> s;

    std::vector<int> freq(256, 0);
    for (char ch : s) {
        freq[static_cast<unsigned char>(ch)]++;
    }

    for (char ch : s) {
        if (freq[static_cast<unsigned char>(ch)] > k) {
            std::cout << "NO";
            return 0;
        }
    }

    std::cout << "YES" << std::endl;
    return 0;
}

